mapper.select:
/*IGNORE_ORG*/
SELECT COUNT(1) FROM job


        AND job_name = #{jobName}


        AND job_category = CAST(#{jobCategory} AS job_category)


        AND image = #{image}

/*IGNORE_ORG*/
SELECT
,
COALESCE((
SELECT jsonb_agg(DISTINCT ji.input_repo_id)
FROM job_input ji
WHERE ji.job_id = j.job_id
), '[]'::jsonb) AS input_repo_ids,
COALESCE((
SELECT jsonb_agg(DISTINCT jo.output_repo_id)
FROM job_output jo
WHERE jo.job_id = j.job_id
), '[]'::jsonb) AS output_repo_ids
FROM job j


        AND j.job_name = #{jobName}


        AND j.job_category = CAST(#{jobCategory} AS job_category)


        AND j.image = #{image}


ORDER BY created_at DESC
LIMIT #{size} OFFSET #{offset}
